const input = $input.first().json;
const slots = Array.isArray(input.slots) ? input.slots : [];
const avoidRain = input.avoid_rain === true;
const needWeather = avoidRain && slots.length > 0 && slots.some((s) => s.is_outdoor !== false);
const location = input.location ? String(input.location).trim() : '';
const warnings = [];
let needGeocode = false;
if (needWeather) {
  if (location) needGeocode = true;
  else warnings.push({ code: 'LOCATION_MISSING', message: 'Chua co dia diem; dung toa do TP.HCM (10.7769, 106.7009) de kiem tra thoi tiet.' });
}
const dates = slots.flatMap((s) => [String(s.start_time).slice(0, 10), String(s.end_time).slice(0, 10)]).sort();
return [{ json: {
  need_weather: needWeather, need_geocode: needGeocode, location,
  lat: 10.7769, lon: 106.7009, location_label: location || 'TP.HCM (mac dinh)',
  start_date: dates[0] || null, end_date: dates[dates.length - 1] || null,
  slots, avoid_rain: avoidRain, warnings
} }];

const p = $input.first().json;
return [{ json: {
  weather_checked: false,
  slots: p.slots.map((s) => ({ ...s, rain_probability: s.rain_probability ?? null })),
  warnings: p.warnings, location_label: p.location_label, used_default_location: false
} }];

const prep = $('Prepare Weather Query').first().json;
let lat = prep.lat, lon = prep.lon, label = prep.location_label;
let usedDefault = !prep.location;
const warnings = [...prep.warnings];
if (prep.need_geocode) {
  let geo = null;
  try { geo = $('Geocode Location').first().json; } catch (e) { geo = null; }
  const hit = geo && Array.isArray(geo.results) ? geo.results[0] : null;
  if (hit) {
    lat = hit.latitude; lon = hit.longitude;
    label = hit.name + (hit.country ? ', ' + hit.country : '');
    usedDefault = false;
  } else {
    usedDefault = true; label = 'TP.HCM (mac dinh)';
    warnings.push({ code: 'LOCATION_NOT_FOUND', message: 'Khong tim thay dia diem "' + prep.location + '"; dung toa do TP.HCM de kiem tra thoi tiet.' });
  }
}
return [{ json: { lat, lon, location_label: label, used_default_location: usedDefault, warnings, start_date: prep.start_date, end_date: prep.end_date } }];

const ctx = $('Resolve Coordinates').first().json;
const prep = $('Prepare Weather Query').first().json;
const res = $input.first().json;
const warnings = [...ctx.warnings];
const slots = prep.slots;
const h = res && res.hourly;
const OFFSET = 7 * 3600000, HOUR = 3600000;
const toMs = (s) => new Date(String(s).replace(' ', 'T') + '+07:00').getTime();
const keyOf = (ms) => new Date(ms + OFFSET).toISOString().slice(0, 13) + ':00'; // YYYY-MM-DDTHH:00
const r1 = (x) => Math.round(x * 10) / 10;

if (!h || !Array.isArray(h.time) || res.error) {
  warnings.push({ code: 'WEATHER_UNAVAILABLE', message: 'Khong lay duoc du bao thoi tiet; rain_probability de trong.' });
  return [{ json: { weather_checked: false, slots: slots.map((s) => ({ ...s, rain_probability: null })), weather_rows: [], warnings, location_label: ctx.location_label, used_default_location: ctx.used_default_location } }];
}

const idx = {};
h.time.forEach((t, i) => { idx[t] = { p: h.precipitation_probability?.[i], t: h.temperature_2m?.[i], r: h.precipitation?.[i] }; });
const used = {};
const out = slots.map((s) => {
  const a = toMs(s.start_time), b = toMs(s.end_time);
  let maxP = null, tSum = 0, tN = 0, rain = 0;
  for (let t = Math.floor((a + OFFSET) / HOUR) * HOUR - OFFSET; t < b; t += HOUR) {
    const k = keyOf(t); const row = idx[k];
    if (!row) continue;
    used[k] = row;
    if (typeof row.p === 'number') maxP = maxP === null ? row.p : Math.max(maxP, row.p);   // MAX theo quy tac
    if (typeof row.t === 'number') { tSum += row.t; tN++; }
    if (typeof row.r === 'number') rain += row.r;
  }
  return { ...s, rain_probability: maxP, temperature: tN ? r1(tSum / tN) : null, rain_mm: r1(rain) };
});
if (out.every((s) => s.rain_probability === null)) warnings.push({ code: 'WEATHER_UNAVAILABLE', message: 'Du bao khong phu khung gio de xuat.' });

const weather_rows = Object.keys(used).map((k) => ({
  location: ctx.location_label, forecast_time: k.replace('T', ' ') + ':00',
  temperature: used[k].t ?? null, precipitation_probability: used[k].p ?? null, rain_mm: used[k].r ?? null
}));
return [{ json: { weather_checked: true, slots: out, weather_rows, warnings, location_label: ctx.location_label, used_default_location: ctx.used_default_location } }];

const a = $('Attach Rain Probability').first().json;
const { weather_rows, ...rest } = a;
return [{ json: rest }];
